mapper.select:




SELECT w.id FROM workorder w
JOIN mes_production_execution e ON e.workorder_id=w.id AND e.status != #{cancelled}
LEFT JOIN mes_execution_completion c ON c.execution_id=e.id
WHERE w.status=#{released} AND w.source=#{local} AND w.id > #{after}
GROUP BY w.id
HAVING SUM(CASE WHEN e.status != #{completed} OR c.id IS NULL THEN 1 ELSE 0 END)=0
ORDER BY w.id LIMIT #{limit}
